const ZONES = [{"id":"neck","n":"Шея","full":"Шея и воротниковая зона","th":["th_neck"],"test":"neckhold","why":"Голова весит около 5 кг. Когда она уходит вперёд, нагрузка на шею растёт в разы: отсюда напряжение, головные боли и скованность.","steps":[{"n":"Освободить","goal":"Снять напряжение и вернуть мягкую подвижность","ex":[["neck_stretch","30 с на сторону"],["neck9","по 3 раза"],["shoulder_circles","45 с"]],"check":"Повороты головы в обе стороны без боли."},{"n":"Включить","goal":"Научить голову стоять над плечами","ex":[["chin_tuck","10 × 5 с"],["wall_angels","2×8"],["prone_ytw","6 на каждую букву"]],"check":"Подбородок назад 10 раз подряд без напряжения спереди шеи."},{"n":"Укрепить","goal":"Выносливость глубоких мышц шеи","ex":[["chin_lift","5 × 10 с"],["neck_iso","по 10 с в 4 стороны"],["prone_neck","8 × 3 с"]],"check":"Удержание головы лёжа — 20 секунд."},{"n":"Нагрузить","goal":"Контроль шеи в движении и под весом","ex":[["quad_neck","6 в каждую сторону"],["face_pull","2×15"],["carry","3×30 м"]],"check":"Удержание головы лёжа — 30 секунд."},{"n":"Усилить","goal":"Сильная шея и плечевой пояс","ex":[["tgu","3×1 на сторону"],["carry","3×40 м"],["pullup","3×5"]],"check":"Удержание головы лёжа — 40 секунд и 5 подтягиваний."}]},{"id":"shoulders","n":"Плечи","full":"Плечевые суставы","th":["th_shoulder"],"test":"shoulder","why":"Работа за компьютером и телефон тянут плечи вперёд. Лопатка теряет опору, и плечо начинает болеть при подъёме руки.","steps":[{"n":"Освободить","goal":"Разгрузить сустав и вернуть объём движений","ex":[["pendulum","1 мин на руку"],["pec_stretch","30 с на сторону"],["thread_needle","6 на сторону"]],"check":"Рука поднимается вверх без боли."},{"n":"Включить","goal":"Контроль лопатки","ex":[["scap_pushup","2×10"],["wall_angels","2×10"],["prone_ytw","8 на каждую букву"]],"check":"Ангелы у стены: руки касаются стены всю амплитуду."},{"n":"Укрепить","goal":"Вращательная манжета и задняя поверхность плеча","ex":[["ext_rot","2×15"],["face_pull","3×15"],["row","3×12"],["pushup","3×8"]],"check":"10 отжиманий с ровным телом."},{"n":"Нагрузить","goal":"Работа над головой","ex":[["overhead_press","3×8"],["vertical_pull","3×8"],["hang","3×20 с"]],"check":"Вис 30 секунд."},{"n":"Усилить","goal":"Сила плечевого пояса","ex":[["pullup","4×5"],["dips","3×6"],["tgu","3×1 на сторону"]],"check":"5 подтягиваний и 8 отжиманий на брусьях."}]},{"id":"posture","n":"Осанка","full":"Осанка и грудной отдел","th":["th_posture"],"test":"wall","why":"Сутулость — это привычка тела, а не лень. Грудной отдел теряет подвижность, а мышцы между лопатками слабеют.","steps":[{"n":"Освободить","goal":"Подвижный грудной отдел","ex":[["cat_cow","8 раз"],["open_book","6 на сторону"],["thread_needle","6 на сторону"],["childs_pose","1 мин"]],"check":"Открытая книга: плечо почти касается пола."},{"n":"Включить","goal":"Разгибатели спины и лопатки","ex":[["chin_tuck","8 × 5 с"],["wall_angels","2×10"],["prone_extension","2×8"],["wall_roll_down","5 раз"]],"check":"Тест у стены: затылок касается стены без запрокидывания."},{"n":"Укрепить","goal":"Выносливость спины","ex":[["pil_swan","6 раз"],["pil_swimming","30 с"],["row","3×12"],["face_pull","3×15"]],"check":"Плавание 45 секунд без прогиба в пояснице."},{"n":"Нагрузить","goal":"Ровная спина под весом","ex":[["hinge","3×10"],["carry","3×30 м"],["one_arm_row","3×10 на руку"],["wall_bridge","3×15 с"]],"check":"Румынская тяга с ровной спиной, 10 раз."},{"n":"Усилить","goal":"Сила задней цепи","ex":[["deadlift","4×5"],["pullup","4×5"],["yoga_flow_p","15 мин"]],"check":"Становая тяга с весом, равным половине вашего, 5 раз с ровной спиной."}]},{"id":"lowback","n":"Поясница","full":"Поясница","th":["th_lowback","th_lordosis"],"test":"plank","why":"Поясница страдает от долгого сидения, наклонов с круглой спиной и слабого корпуса. Помогает движение и выносливость мышц вокруг позвоночника.","steps":[{"n":"Освободить","goal":"Снять спазм и найти движение без боли","ex":[["knees_chest","1 мин"],["pelvic_tilt","10 раз"],["sphinx","45 с"],["supine_twist","45 с на сторону"],["childs_pose","1 мин"]],"check":"Наклоны таза лёжа без боли."},{"n":"Включить","goal":"«Большая тройка» и ягодицы","ex":[["curl_up","3 × 5 по 8 с"],["bird_dog","6 на сторону, пауза 5 с"],["dead_bug","2×8 на сторону"],["glute_bridge","2×12"],["hinge_drill","2×10"]],"check":"Птица-собака: 10 секунд на каждую сторону без раскачки."},{"n":"Укрепить","goal":"Выносливость корпуса","ex":[["side_plank","3 × 20–30 с"],["plank","3×30 с"],["pallof","2×10 на сторону"],["hip_flexor_stretch","30 с на сторону"]],"check":"Боковая планка 30 секунд на каждую сторону."},{"n":"Нагрузить","goal":"Наклоны и переноски с весом","ex":[["hinge","3×10"],["suitcase","3×30 м на сторону"],["sl_rdl","3×8 на ногу"],["hip_thrust","3×12"]],"check":"Боковая планка 45 секунд и тяга с ровной спиной."},{"n":"Усилить","goal":"Сила и мощность","ex":[["deadlift","4×5"],["kb_swing","5×10"],["copenhagen","3×20 с"]],"check":"Махи гирей 10 раз с ровной спиной и без боли."}]},{"id":"hips","n":"Таз и ТБС","full":"Таз и тазобедренные суставы","th":["th_hips"],"test":"squat","why":"Восемь часов сидения укорачивают сгибатели бедра и выключают ягодицы. Тазобедренные теряют вращение, и нагрузка уходит в поясницу и колени.","steps":[{"n":"Освободить","goal":"Вращение и раскрытие суставов","ex":[["hip_circles","8 в каждую сторону"],["ninety_ninety","8 переходов"],["figure4","30 с на сторону"],["hip_flexor_stretch","30 с на сторону"]],"check":"Переходы 90/90 без помощи рук."},{"n":"Включить","goal":"Ягодицы и стабилизаторы таза","ex":[["glute_bridge","2×12"],["clamshell","2×15 на сторону"],["pil_side_kicks","10 на сторону"],["lizard","30 с на сторону"]],"check":"Мост на одной ноге 10 раз без перекоса таза."},{"n":"Укрепить","goal":"Присед, выпад, контроль колена","ex":[["squat","3×10"],["lunge","3×8 на ногу"],["band_walk","2 × 12 шагов"],["wall_sit","3×30 с"]],"check":"Глубокий присед 30 секунд с пятками на полу."},{"n":"Нагрузить","goal":"Работа на одной ноге и с весом","ex":[["bss","3×8 на ногу"],["sl_rdl","3×8 на ногу"],["hip_thrust","3×10"],["cossack","3×6 на сторону"]],"check":"Болгарский присед 8 раз на каждую ногу."},{"n":"Усилить","goal":"Мощность бёдер","ex":[["deadlift","4×5"],["kb_swing","8×10"],["copenhagen","3×20 с"],["nordic_curl","3×5"]],"check":"Казацкий присед до пола в обе стороны."}]},{"id":"scoliosis","n":"Сколиоз","full":"Сколиоз и асимметрия","th":["th_scoliosis"],"test":"plank","why":"Небольшая асимметрия есть почти у всех. Упражнения выравнивают силу сторон, учат вытягиваться вдоль оси и уменьшают боль.","note":"При структурном сколиозе больше 20° и у подростков занимайтесь со специалистом по специальной методике, например Шрот. Здесь — общая работа на симметрию.","steps":[{"n":"Освободить","goal":"Подвижность боков и грудного отдела","ex":[["wall_side_reach","30 с на сторону, дольше на тугую"],["open_book","6 на сторону"],["cat_cow","8 раз"],["childs_pose","1 мин"]],"check":"Вы знаете свою тугую сторону."},{"n":"Включить","goal":"Вытяжение вдоль оси","ex":[["wall_elong","5 × 10 с"],["bird_dog","6 на сторону"],["prone_extension","2×8"],["pil_saw","4 на сторону"]],"check":"Вытяжение у стены 10 секунд без задирания подбородка."},{"n":"Укрепить","goal":"Выровнять силу сторон","ex":[["side_plank","3 подхода, на слабую сторону на 1 больше"],["pallof","2×10 на сторону"],["pil_swimming","30 с"]],"check":"Разница в боковой планке между сторонами меньше 10 секунд."},{"n":"Нагрузить","goal":"Нагрузка с одной стороны","ex":[["suitcase","3×30 м на сторону"],["one_arm_row","3×10 на руку"],["hang","3×20 с"]],"check":"Переноска с одной стороны без наклона корпуса."},{"n":"Усилить","goal":"Сила в трёх плоскостях","ex":[["tgu","3×1 на сторону"],["copenhagen","3×20 с"],["pullup","4×5"]],"check":"Турецкий подъём одинаково ровно в обе стороны."}]},{"id":"core","n":"Пресс","full":"Пресс и кор","th":["th_core"],"test":"plankf","why":"Сильный корпус держит позвоночник, когда двигаются руки и ноги. Начинаем с контроля поясницы и идём к ролику и висам.","steps":[{"n":"Включить","goal":"Почувствовать пресс и прижатую поясницу","ex":[["pelvic_tilt","10 раз"],["toe_tap","2×8 на ногу"],["curl_up","3 × 5 по 8 с"]],"check":"Касания пятками 8 раз без отрыва поясницы."},{"n":"Стабилизировать","goal":"Руки и ноги двигаются, корпус — нет","ex":[["dead_bug","2×8 на сторону"],["bird_dog","6 на сторону"],["pil_single_leg","8 на ногу"],["pil_leg_circles","5 в каждую сторону"]],"check":"Мёртвый жук 10 раз на сторону медленно."},{"n":"Укрепить","goal":"Планки и удержания","ex":[["plank","3×40 с"],["side_plank","3×30 с"],["rev_crunch","3×10"],["hollow","3×20 с"],["bear","3×30 с"]],"check":"Планка 60 секунд."},{"n":"Нагрузить","goal":"Антиповорот и вес ног","ex":[["boat","3×20 с"],["plank_tap","2×10 на сторону"],["pallof","3×10 на сторону"],["knee_raise","3×10"],["bicycle","2×10 на сторону"]],"check":"Подъём коленей в висе 10 раз без раскачки."},{"n":"Усилить","goal":"Сила пресса","ex":[["ab_wheel","3×8"],["leg_raise_hang","3×8"],["hollow_rock","3×15"],["l_sit","5×10 с"],["pil_teaser","5 раз"]],"check":"Ролик 8 раз с ровной поясницей."}]},{"id":"pelvic","n":"Тазовое дно","full":"Мужское здоровье: тазовое дно, сосуды, сила","th":["th_men","th_pelvic"],"test":null,"why":"Эрекция и контроль зависят от трёх вещей: мышц тазового дна, здоровья сосудов и общей силы. Поэтому лестница идёт от расслабления и правильного сжатия к кардио, силовым и интервалам.","steps":[{"n":"Расслабить","goal":"Снять зажим в тазу и начать ходить каждый день","ex":[["supine_butterfly","1 мин"],["happy_baby","45 с"],["childs_pose","1 мин"],["walking","20–30 мин в день"]],"check":"Полное расслабление таза на выдохе; ходьба 20–30 минут каждый день."},{"n":"Включить","goal":"Найти мышцы и сжимать правильно","ex":[["pelvic_floor","10 × 5 с и 10 быстрых, лёжа"],["kegel_bridge","2×10, пауза 3 с"],["pelvic_tilt","10 раз"],["butterfly_pulse","45 с"]],"check":"10 сжатий по 5 секунд с полным расслаблением между ними."},{"n":"Укрепить","goal":"Сжатие сидя и стоя плюс кардио для сосудов","ex":[["pelvic_floor","10 × 10 с, сидя и стоя"],["diamond_raise","2×12"],["kneel_thrust","2×12"],["squat_hold","1 мин"],["zone2","30 мин, 3–5 раз в неделю"]],"check":"Удержание 10 секунд стоя; 150 минут кардио в неделю."},{"n":"Нагрузить","goal":"Контроль под весом","ex":[["squat","3×8–10"],["hinge","3×8"],["hip_thrust","3×10, сжатие вверху"],["carry","3×30 м, держать лёгкое сжатие"]],"check":"Сжатие во время приседа и переноски без задержки дыхания."},{"n":"Усилить","goal":"Сила, мощность и выносливость сердца","ex":[["deadlift","3×5"],["kb_swing","5×10"],["bss","3×8 на ногу"],["intervals_4x4","раз в неделю"]],"check":"Контроль при прыжках и беге; интервалы 4×4 раз в неделю."}],"note":"Если есть боль в тазу, жжение или частые позывы, начинайте только с расслабления: лишние сжатия могут усилить симптомы. С такими жалобами сначала к специалисту."},{"id":"feet","n":"Стопы","full":"Стопы и голеностоп","th":["th_feet"],"test":null,"why":"Стопы — фундамент осанки. В тесной обуви их мышцы слабеют, свод проседает, и нагрузка уходит в колени и спину.","steps":[{"n":"Освободить","goal":"Мягкие и подвижные стопы","ex":[["ball_foot","1 мин на стопу"],["toe_yoga","10 раз"],["seiza","1 мин"]],"check":"Пальцы ног двигаются по отдельности."},{"n":"Включить","goal":"Свод стопы","ex":[["short_foot","10 × 5 с"],["calf_raise","2×15"],["barefoot","10 мин"]],"check":"Короткая стопа 10 секунд стоя."},{"n":"Укрепить","goal":"Сила голени и баланс","ex":[["calf_raise","3×12 на одной ноге"],["squat_hold","1 мин"],["wall_sit","3×30 с"]],"check":"Стоять на одной ноге 30 секунд с закрытыми глазами."},{"n":"Нагрузить","goal":"Пружина стопы","ex":[["rope","3×1 мин"],["lunge","3×8 на ногу"],["cossack","3×6 на сторону"]],"check":"Скакалка 2 минуты без боли."}]}];
const ZONE_F = {"pelvic":{"full":"Тазовое дно и женское здоровье","th":["th_women_pelvic","th_pelvic"],"why":"Мышцы тазового дна держат органы малого таза и отвечают за контроль мочеиспускания. После родов, с возрастом и при тяжёлых нагрузках они слабеют — отсюда подтекание при кашле, смехе и прыжках. Важно и укреплять, и полностью расслаблять.","note":"После родов начинайте, когда врач разрешит нагрузку. При боли в тазу, ощущении тяжести или опущения — сначала к специалисту.","steps":[{"n":"Расслабить","goal":"Снять зажим в области таза","ex":[["supine_butterfly","1 мин"],["happy_baby","45 с"],["childs_pose","1 мин"],["knees_chest","45 с"]],"check":"Вы чувствуете полное расслабление таза."},{"n":"Включить","goal":"Найти мышцы и сжимать правильно","ex":[["pelvic_floor","10 × 3–5 с и 10 быстрых"],["pelvic_tilt","10 раз"],["kegel_bridge","2×10, пауза 3 с"],["clamshell","2×12 на сторону"]],"check":"10 сжатий по 5 секунд с полным расслаблением между ними."},{"n":"Укрепить","goal":"Тазовое дно вместе с ягодицами и прессом","ex":[["kegel_bridge","2×12, пауза 5 с"],["glute_bridge","2×12"],["dead_bug","2×8 на сторону"],["squat_hold","45 с"]],"check":"Удержание 10 секунд сидя и стоя, без подтекания при кашле."},{"n":"Нагрузить","goal":"Контроль в движении и под весом","ex":[["hip_thrust","3×10"],["squat","3×10"],["lunge","2×8 на ногу"],["carry","3×30 м"]],"check":"Сжатие в приседе и при переноске без задержки дыхания."},{"n":"Усилить","goal":"Прыжки и бег без подтекания","ex":[["kb_swing","5×10"],["bounce","1 мин"],["rope","3×1 мин"]],"check":"Прыжки и бег без подтекания и тяжести."}]},"core":{"th":["th_core","th_diastasis"],"note":"После беременности проверьте расхождение мышц живота (урок «Расхождение мышц живота»). Если щель шире двух пальцев — оставайтесь на первых двух шагах, без скручиваний и тяжёлых планок, и покажитесь специалисту."}};
const TEXT_F = {"ex":{"zone2":{"why":"Долгая спокойная работа развивает выносливость сердца и сосудов и помогает держать вес. Это основа выносливости для любых целей."}},"th":{"th_pelvic":{"p0":"Мышцы тазового дна поддерживают органы малого таза, отвечают за контроль мочеиспускания и работают вместе с прессом и диафрагмой. У женщин их тренировка помогает при подтекании мочи, после родов и в период менопаузы."}}};
const DOSE_F = {"pushup":"с опоры, если тяжело","pullup":"с резинкой или только опускание","dips":"с резинкой"};
